import{_ as e,o as l,c as t,R as i}from"./chunks/framework.CukUnDQI.js";const _=JSON.parse('{"title":"腾讯 2025","description":"","frontmatter":{},"headers":[],"relativePath":"work/tencent/2025.md","filePath":"work/tencent/2025.md","lastUpdated":1769331326000}'),o={name:"work/tencent/2025.md"};function r(n,a,s,c,d,p){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="腾讯-2025" tabindex="-1">腾讯 2025 <a class="header-anchor" href="#腾讯-2025" aria-label="Permalink to &quot;腾讯 2025&quot;">​</a></h1><h2 id="_2025-工作展望" tabindex="-1">2025 工作展望 <a class="header-anchor" href="#_2025-工作展望" aria-label="Permalink to &quot;2025 工作展望&quot;">​</a></h2><p>春节结束了，开始投入到紧张的工作中了，春节回来这几天还在找状态。开始忙起来之前，先对工作做一些展望吧：</p><ol><li>第一点：今年可以预期的是业务开发会非常非常忙，因为项目组的人力会有一些变动，今年最重要的事情，专注业务，先把业务 cover 下来，能够独当一面，保障业务的平稳发展，提升自己的表现。</li><li>第二点：去年其实是有一些意料之外的事情发生的，导致跟自己的计划其实有一些出入，年初计划的事情，没办法顺利开展。今年很多事情是预料的，回顾去年一整年，整个状态是比较紧张，有一些慌乱的，没有在自己最好的状态，今年需要自己投入更多的时间和精力到工作中，找回自己的节奏。</li><li>第三点：去年少了很多对工作的总结，博客的更新少了很多，今年在这一方面要补齐，重新建设起来。</li></ol><h2 id="_2025-总结" tabindex="-1">2025 总结 <a class="header-anchor" href="#_2025-总结" aria-label="Permalink to &quot;2025 总结&quot;">​</a></h2><p>今年很少写博客，工作实在是太忙了，2025 年是工作以来最忙的一年，也是成长最快的一年，今年的收获有下面几个：</p><ol><li>终于晋升了 9 级：在 8 级停留了两年半后，在腾讯待的第三个团队，终于晋升了 9 级。</li><li>担任业务的负责人：今年由于人员变动的原因，成了一个项目的负责人，体会到了完全不一样的工作职责。</li><li>重新拿到了高绩效：距离上一次拿到高绩效已经过去两年了，在这个团队找到了自己的节奏，获得了认可。</li><li>高增长业务：第一次在部门最高增长的业务里，伴随业务一起成长。</li><li>指导新成员融入：由于业务的增长，补充了新的成员，收获了指导新成员融入团队的经验。</li></ol><p>2025 年不管是生活还是工作中，都是收获满满的一年，同时也发现自己有挺多不足的地方:</p><ol><li>拖延症没有完全治好，工作还需要更高效。</li><li>在 AI 上没有太多的探索，还是停留在基本的使用上。</li><li>没有持续总结自己，多年来养成的好习惯被繁忙的工作冲击。</li><li>对未来的规划还不够，很多事情都是被其他力量推着走。</li></ol><p>2026 继续前行 💪 ！！！</p>',10)])])}const m=e(o,[["render",r]]);export{_ as __pageData,m as default};
